import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class Main {
    private static final ThreadLocal<String> REQUEST_ID = new ThreadLocal<>();
    private static final InheritableThreadLocal<String> INHERITED = new InheritableThreadLocal<>();

    public static void main(String[] args) throws Exception {
        demonstrateThreadPoolResidue();
        demonstrateCorrectCleanup();
        demonstrateInheritableThreadLocalBoundary();
    }

    // 场景 1：没有 remove，下一个任务读到残留值（串数据）
    static void demonstrateThreadPoolResidue() throws Exception {
        ExecutorService pool = Executors.newSingleThreadExecutor();
        try {
            Future<String> first = pool.submit(() -> {
                REQUEST_ID.set("REQ-A");
                return REQUEST_ID.get();
            });
            System.out.println("first request=" + first.get());

            // 第二个任务没有 set，但 get 读到了上一个任务的残留值
            String leaked = pool.submit(REQUEST_ID::get).get();
            System.out.println("next task sees=" + leaked);
            assert "REQ-A".equals(leaked) : "串数据：新任务读到了旧请求的 requestId";
        } finally {
            pool.shutdownNow();
        }
    }

    // 场景 2：用 try/finally remove，正确清理
    static void demonstrateCorrectCleanup() throws Exception {
        ExecutorService pool = Executors.newSingleThreadExecutor();
        try {
            String cleaned = pool.submit(() -> {
                try {
                    REQUEST_ID.set("REQ-B");
                    return REQUEST_ID.get();
                } finally {
                    REQUEST_ID.remove(); // 必须在 finally 中清理
                }
            }).get();
            System.out.println("cleaned request=" + cleaned);

            // remove 后，后续任务读不到旧值
            String afterClean = pool.submit(REQUEST_ID::get).get();
            System.out.println("after clean=" + afterClean);
            assert afterClean == null : "清理后不应读到旧值";
        } finally {
            pool.shutdownNow();\        }
    }

    // 场景 3：InheritableThreadLocal 不按任务重新复制
    static void demonstrateInheritableThreadLocalBoundary() throws Exception {
        ExecutorService pool = Executors.newSingleThreadExecutor();
        try {
            INHERITED.set("parent-1");
            // worker 在 pool 初始化时创建，此时不继承当前线程的值（行为取决于创建时机）
            String first = pool.submit(INHERITED::get).get();
            System.out.println("inherited first=" + first);

            // 修改提交者线程的值，worker 不会重新继承
            INHERITED.set("parent-2");
            String second = pool.submit(INHERITED::get).get();
            System.out.println("inherited second=" + second);
            // 值不变：worker 的 inheritableThreadLocals 是创建时的一次性复制
        } finally {
            INHERITED.remove();
            pool.shutdownNow();
        }
    }
}
